INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('183e992f-ce19-4f65-980d-897b462aa522', 'c3c3c3c3-3030-4000-8000-000000000003', 16, 'Dia 16 — Discernimento', 'Semana 3: Discernir', '{"pch": "Provai os esp\u00edritos\u2026 Nem todo pensamento que surge \u00e9 verdadeiro. Discernir \u00e9 separar.", "verse": "1Jo 4,1", "lectio": "Leia 1Jo 4,1-6. O esp\u00edrito da verdade.", "practice": "Hoje, antes de agir por impulso, pergunte: isso vem da paz ou da ansiedade?", "question": "Como voc\u00ea distingue um pensamento \u00fatil de um destrutivo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('39521ae4-ffb9-43ae-b257-192f8330ce80', 'c3c3c3c3-3030-4000-8000-000000000003', 17, 'Dia 17 — Intuição', 'Semana 3: Discernir', '{"pch": "O Esp\u00edrito da verdade vos guiar\u00e1\u2026 Intui\u00e7\u00e3o espiritual \u00e9 o GPS divino.", "verse": "Jo 16,13", "lectio": "Leia Jo 16,12-15. O Esp\u00edrito ensina.", "practice": "Tome uma decis\u00e3o pequena hoje usando apenas intui\u00e7\u00e3o e ora\u00e7\u00e3o.", "question": "Quando sua intui\u00e7\u00e3o te guiou corretamente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3c5ad66f-3af6-43a7-a225-7aa6f232da86', 'c3c3c3c3-3030-4000-8000-000000000003', 18, 'Dia 18 — Paciência', 'Semana 3: Discernir', '{"pch": "A perseveran\u00e7a tenha obra perfeita\u2026 Clareza raramente \u00e9 instant\u00e2nea. \u00c0s vezes, esperar \u00e9 a resposta.", "verse": "Tg 1,4", "lectio": "Leia Tg 1,2-4. Alegria nas prova\u00e7\u00f5es.", "practice": "Espere antes de responder algo hoje. Observe o que muda.", "question": "Em que \u00e1rea da vida voc\u00ea precisa de mais paci\u00eancia?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('58587bc7-c34a-4cff-834a-6abdb165c3ad', 'c3c3c3c3-3030-4000-8000-000000000003', 19, 'Dia 19 — Perspectiva', 'Semana 3: Discernir', '{"pch": "Os meus pensamentos n\u00e3o s\u00e3o os vossos pensamentos\u2026 \u00c0s vezes, clareza \u00e9 aceitar que voc\u00ea n\u00e3o v\u00ea tudo.", "verse": "Is 55,8-9", "lectio": "Leia Is 55,6-11. A palavra que n\u00e3o volta vazia.", "practice": "Escreva sua situa\u00e7\u00e3o atual como se fosse Deus descrevendo-a para voc\u00ea.", "question": "O que mudaria se voc\u00ea visse sua situa\u00e7\u00e3o do ponto de vista de Deus?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7dc18a7c-f96b-41c1-8ac6-60b3db7444e4', 'c3c3c3c3-3030-4000-8000-000000000003', 20, 'Dia 20 — Soltar', 'Semana 3: Discernir', '{"pch": "Lan\u00e7a sobre o Senhor o teu fardo\u2026 Pensamentos obsessivos s\u00e3o fardos que n\u00e3o te pertencem.", "verse": "Sl 55,22", "lectio": "Leia Sl 55,16-23. Deus sustenta.", "practice": "Escreva o pensamento que te atormenta num papel. Depois, rasgue-o como ato simb\u00f3lico.", "question": "Que pensamento voc\u00ea precisa parar de carregar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('a80a6282-9cba-41df-99a0-7c50d3cc0798', 'c3c3c3c3-3030-4000-8000-000000000003', 21, 'Dia 21 — Ordem interior', 'Semana 3: Discernir', '{"pch": "Deus n\u00e3o \u00e9 de confus\u00e3o, mas de paz\u2026 A ordem interior reflete a ordem divina.", "verse": "1Cor 14,33", "lectio": "Leia 1Cor 14,26-33. Ordem no culto.", "practice": "Organize algo externo (mesa, quarto, agenda) como reflexo da ordem interna que busca.", "question": "O que na sua vida interna est\u00e1 bagun\u00e7ado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('68bfdebc-e08e-4eca-b3a9-27d1160b6c90', 'c3c3c3c3-3030-4000-8000-000000000003', 22, 'Dia 22 — Atenção', 'Semana 4: Integrar', '{"pch": "Cuidado com o modo como voc\u00eas ouvem\u2026 Aten\u00e7\u00e3o \u00e9 a ora\u00e7\u00e3o mais b\u00e1sica.", "verse": "Lc 8,18", "lectio": "Leia Lc 8,16-18. A l\u00e2mpada e a aten\u00e7\u00e3o.", "practice": "Pratique aten\u00e7\u00e3o plena numa atividade simples: comer, caminhar, respirar.", "question": "No que voc\u00ea tem prestado aten\u00e7\u00e3o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('ffed5b73-6714-4a5d-bcfd-649a6ad5a7dc', 'c3c3c3c3-3030-4000-8000-000000000003', 23, 'Dia 23 — Rotina', 'Semana 4: Integrar', '{"pch": "Daniel orava tr\u00eas vezes ao dia\u2026 Rotina sagrada cria espa\u00e7o para clareza.", "verse": "Dn 6,10", "lectio": "Leia Dn 6,6-13. A fidelidade de Daniel.", "practice": "Crie uma rotina matinal de 15 min: sil\u00eancio, leitura, ora\u00e7\u00e3o.", "question": "Como \u00e9 sua rotina matinal? Ela alimenta ou drena sua mente?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f4e9174e-8067-45cb-97bd-56e0628f5b55', 'c3c3c3c3-3030-4000-8000-000000000003', 24, 'Dia 24 — Contentamento', 'Semana 4: Integrar', '{"pch": "Aprendi a estar contente em toda situa\u00e7\u00e3o\u2026 Contentamento n\u00e3o \u00e9 conformismo \u2014 \u00e9 liberdade.", "verse": "Fl 4,11", "lectio": "Leia Fl 4,10-13. O segredo de Paulo.", "practice": "Liste 10 coisas que j\u00e1 tem e que algu\u00e9m sonha em ter.", "question": "O que te falta para ser feliz? Ser\u00e1 que realmente falta?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bcc2b146-9844-4222-b920-924ad03d7c3b', 'c3c3c3c3-3030-4000-8000-000000000003', 25, 'Dia 25 — Criatividade', 'Semana 4: Integrar', '{"pch": "No princ\u00edpio, Deus criou\u2026 Criatividade \u00e9 imagem de Deus em a\u00e7\u00e3o. Mentes claras criam.", "verse": "Gn 1,1", "lectio": "Leia Gn 1,1-5. O primeiro ato criativo.", "practice": "Crie algo hoje: um texto, um desenho, uma m\u00fasica, uma receita.", "question": "O que voc\u00ea criaria se tivesse clareza?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('41a9b8e8-9f49-47c6-a8b8-bd1084b4a01e', 'c3c3c3c3-3030-4000-8000-000000000003', 26, 'Dia 26 — Palavras', 'Semana 4: Integrar', '{"pch": "A morte e a vida est\u00e3o no poder da l\u00edngua\u2026 O que voc\u00ea diz molda o que voc\u00ea pensa.", "verse": "Pv 18,21", "lectio": "Leia Pv 18,20-21. O fruto da boca.", "practice": "Hoje, fale apenas o que edifica. Observe como isso muda seu estado mental.", "question": "Que palavras voc\u00ea repete sobre si mesmo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b90cea0d-39c9-41de-a0d0-39a1b35457af', 'c3c3c3c3-3030-4000-8000-000000000003', 27, 'Dia 27 — Direção', 'Semana 4: Integrar', '{"pch": "L\u00e2mpada para os meus p\u00e9s\u2026 A Palavra n\u00e3o ilumina o caminho todo \u2014 s\u00f3 o pr\u00f3ximo passo.", "verse": "Sl 119,105", "lectio": "Leia Sl 119,105-112. Luz suficiente.", "practice": "Defina 1 pr\u00f3ximo passo claro. N\u00e3o o segundo. S\u00f3 o primeiro.", "question": "Qual \u00e9 o pr\u00f3ximo passo que voc\u00ea precisa dar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7fded1c2-46aa-483e-a0c5-3b254ebf399f', 'c3c3c3c3-3030-4000-8000-000000000003', 28, 'Dia 28 — Confiança', 'Semana 4: Integrar', '{"pch": "Confia no Senhor\u2026 e n\u00e3o te estribes no teu pr\u00f3prio entendimento. Clareza final vem da rendi\u00e7\u00e3o.", "verse": "Pv 3,5-6", "lectio": "Leia Pv 3,1-8. O caminho da confian\u00e7a.", "practice": "Entregue uma decis\u00e3o a Deus hoje. Confie sem entender.", "question": "Em que \u00e1rea voc\u00ea tenta entender quando deveria confiar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6ac00f54-adf7-4709-8814-c82ec54c3c00', 'c3c3c3c3-3030-4000-8000-000000000003', 29, 'Dia 29 — Paz mental', 'Semana 4: Integrar', '{"pch": "A paz de Deus que excede todo entendimento\u2026 guardar\u00e1 vosso cora\u00e7\u00e3o e mente. Paz que a l\u00f3gica n\u00e3o explica.", "verse": "Fl 4,7", "lectio": "Leia Fl 4,6-7. Ora\u00e7\u00e3o que gera paz.", "practice": "Ore sobre cada preocupa\u00e7\u00e3o. Depois, agrade\u00e7a como se j\u00e1 tivesse a resposta.", "question": "O que significaria ter paz mental de verdade?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('245fdff3-766d-4c27-b4d3-acdfbf435181', 'c3c3c3c3-3030-4000-8000-000000000003', 30, 'Dia 30 — Mente clara', 'Semana 4: Integrar', '{"pch": "Deus nos deu esp\u00edrito de poder, amor e mente s\u00e3\u2026 Clareza mental n\u00e3o \u00e9 destino \u2014 \u00e9 pr\u00e1tica di\u00e1ria.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar a chama.", "practice": "Releia todas as reflex\u00f5es. Escreva seu manifesto de clareza mental em 5 frases.", "question": "O que mudou na sua mente nesses 30 dias?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('6248ed3e-911f-46ee-ad1f-d94b08f19285', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 1, 'O olhar que se volta', NULL, '{"intro": "Psicologicamente, aceitar a exist\u00eancia de uma dor \u00e9 o in\u00edcio do fim do trauma.", "prayer": "Escreva sobre essa ferida sem filtros.", "practice": "Reserve 5 minutos para olhar honestamente para algo que lhe d\u00f3i.", "reflection": "A ferida s\u00f3 pode ser curada quando deixamos de escond\u00ea-la de n\u00f3s mesmos. O primeiro passo \u00e9 o reconhecimento.", "journal_prompt": "O que em voc\u00ea ainda tem medo de ser visto?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7f70a32a-9138-415d-bd27-f56ce3062fe6', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 2, 'O perdão como libertação', NULL, '{"intro": "O ressentimento \u00e9 uma pris\u00e3o que voc\u00ea constr\u00f3i para o outro e acaba morando nela.", "prayer": "Em sil\u00eancio, pronuncie: Eu o libero, eu me libero.", "practice": "Identifique uma pessoa ou situa\u00e7\u00e3o que voc\u00ea ainda carrega.", "reflection": "Perdoar n\u00e3o \u00e9 esquecer, \u00e9 tirar o peso do passado dos seus ombros.", "journal_prompt": "Qual peso voc\u00ea est\u00e1 pronto para soltar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('77eaa697-dc89-43bd-ab9f-361cc131577b', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 3, 'A voz que consola', NULL, '{"intro": "O trauma nos isola; a cura nos reconecta \u00e0 nossa pr\u00f3pria dignidade.", "prayer": "Fique em sil\u00eancio absoluto por 10 minutos.", "practice": "Respire fundo e imagine-se sendo abra\u00e7ado pelo amor que nunca falha.", "reflection": "A cura vem de uma voz que sussurra: voc\u00ea n\u00e3o est\u00e1 mais sozinho.", "journal_prompt": "Se o amor falasse com voc\u00ea hoje, o que diria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c4566c85-797e-499d-ae19-11db3cea8862', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 4, 'Desapego do passado', NULL, '{"intro": "Tentar viver no passado \u00e9 tentar preencher um vaso quebrado com areia.", "prayer": "Queime esse papel simbolicamente ou rasgue-o.", "practice": "Liste tr\u00eas coisas que te mant\u00eam preso ao que j\u00e1 passou.", "reflection": "O passado \u00e9 um espelho, n\u00e3o uma morada.", "journal_prompt": "Quem voc\u00ea seria se n\u00e3o carregasse esse passado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bb55db15-57da-46f0-bb9f-f8ae171b0372', 'f0f35259-85b3-44fa-99c1-4f9ec87c9f4d', 5, 'A nova identidade', NULL, '{"intro": "A cura redefine sua narrativa pessoal.", "prayer": "Afirme essas qualidades em voz alta.", "practice": "Defina-se agora com tr\u00eas qualidades que n\u00e3o dependem da sua dor.", "reflection": "Voc\u00ea n\u00e3o \u00e9 o que te aconteceu, voc\u00ea \u00e9 o que voc\u00ea escolhe fazer com isso.", "journal_prompt": "Como \u00e9 a sua vida quando voc\u00ea aceita quem voc\u00ea realmente \u00e9?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
